function main(): void {
  console.log(new TextDecoder("utf-16le").decode(new Uint8Array([104, 0, 105, 0])));
  console.log(new TextDecoder("utf-16le").decode(new Uint8Array([0x3d, 0xd8, 0x00, 0xde, 0x41, 0])));
